args.content:
/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Georgia, 'Times New Roman', serif;
    line-height: 1.6;
    color: #333;
    background-color: #fffaf5;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, #8b4513 0%, #d2691e 100%);
    color: white;
    text-align: center;
    padding: 80px 20px;
}

.hero h1 {
    font-size: 3rem;
    margin-bottom: 10px;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.tagline {
    font-size: 1.5rem;
    font-style: italic;
    margin-bottom: 10px;
}

.subtitle {
    font-size: 1.1rem;
    opacity: 0.9;
}

/* Navigation */
.navbar {
    background-color: #5c3a1e;
    padding: 15px 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.nav-links {
    list-style: none;
    display: flex;
    justify-content: center;
    gap: 30px;
}

.nav-links a {
    color: white;
    text-decoration: none;
    font-size: 1.1rem;
    padding: 5px 15px;
    border-radius: 5px;
    transition: background-color 0.3s;
}

.nav-links a:hover {
    background-color: #8b4513;
}

/* Menu Section */
.menu-section {
    padding: 60px 20px;
    max-width: 1200px;
    margin: 0 auto;
}

.menu-section h2 {
    text-align: center;
    font-size: 2.5rem;
    margin-bottom: 40px;
    color: #5c3a1e;
}

.menu-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 30px;
}

.menu-item {
    background: white;
    padding: 25px;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    transition: transform 0.3s, box-shadow 0.3s;
}

.menu-item:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 12px rgba(0,0,0,0.15);
}

.menu-item h3 {
    color: #8b4513;
    font-size: 1.4rem;
    margin-bottom: 10px;
}

.menu-item p {
    color: #666;
    margin-bottom: 15px;
    font-size: 0.95rem;
}

.price {
    display: inline-block;
    background-color: #d2691e;
    color: white;
    padding: 8px 15px;
    border-radius: 20px;
    font-weight: bold;
    font-size: 1.1rem;
}

/* Hours Section */
.hours-section {
    background-color: #f5e6d3;
    padding: 60px 20px;
}

.hours-section h2 {
    text-align: center;
    font-size: 2.5rem;
    margin-bottom: 40px;
    color: #5c3a1e;
}

.hours-table {
    max-width: 600px;
    margin: 0 auto;
}

.hours-row {
    display: flex;
    justify-content: space-between;
    padding: 15px 20px;
    border-bottom: 1px solid #d2b48c;
    font-size: 1.1rem;
}

.hours-row:last-child {
    border-bottom: none;
}

.hours-row span:first-child {
    font-weight: bold;
    color: #5c3a1e;
}

/* Contact Section */
.contact-section {
    padding: 60px 20px;
    max-width: 600px;
    margin: 0 auto;
}

.contact-section h2 {
    text-align: center;
    font-size: 2.5rem;
    margin-bottom: 40px;
    color: #5c3a1e;
}

.contact-form {
    background: white;
    padding: 30px;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    font-weight: bold;
    color: #5c3a1e;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 12px;
    border: 2px solid #ddd;
    border-radius: 5px;
    font-family: inherit;
    font-size: 1rem;
    transition: border-color 0.3s;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #8b4513;
}

.submit-btn {
    background-color: #8b4513;
    color: white;
    padding: 15px 30px;
    border: none;
    border-radius: 5px;
    font-size: 1.1rem;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.3s;
}

.submit-btn:hover {
    background-color: #5c3a1e;
}

.thank-you-message {
    display: none;
    text-align: center;
    padding: 30px;
    background: #e8f5e9;
    border-radius: 10px;
    margin-top: 20px;
}

.thank-you-message h3 {
    color: #2e7d32;
    font-size: 1.8rem;
    margin-bottom: 10px;
}

.thank-you-message p {
    color: #555;
}

/* Footer */
.footer {
    background-color: #5c3a1e;
    color: white;
    text-align: center;
    padding: 30px 20px;
}

.footer p {
    margin: 5px 0;
    opacity: 0.9;
}

/* Responsive Design */
@media (max-width: 768px) {
    .hero h1 {
        font-size: 2.2rem;
    }

    .tagline {
        font-size: 1.2rem;
    }

    .nav-links {
        gap: 15px;
    }

    .nav-links a {
        font-size: 1rem;
        padding: 5px 10px;
    }

    .menu-section h2,
    .hours-section h2,
    .contact-section h2 {
        font-size: 2rem;
    }

    .menu-grid {
        grid-template-columns: 1fr;
    }

    .hours-row {
        font-size: 1rem;
        padding: 12px 15px;
    }
}

@media (max-width: 480px) {
    .hero {
        padding: 50px 15px;
    }

    .hero h1 {
        font-size: 1.8rem;
    }

    .navbar {
        padding: 10px 0;
    }

    .nav-links {
        gap: 10px;
    }

    .menu-section,
    .hours-section,
    .contact-section {
        padding: 40px 15px;
    }

    .contact-form {
        padding: 20px;
    }
}

document.addEventListener('DOMContentLoaded', function() {
    const contactForm = document.getElementById('contact-form');
    const thankYouMessage = document.getElementById('thank-you');

    contactForm.addEventListener('submit', function(event) {
        event.preventDefault(); // Prevent page reload

        // Get form values
        const name = document.getElementById('name').value;
        const email = document.getElementById('email').value;
        const message = document.getElementById('message').value;

        // Simple validation
        if (name && email && message) {
            // Hide the form and show the thank-you message
            contactForm.style.display = 'none';
            thankYouMessage.style.display = 'block';

            // Optional: Reset form values
            contactForm.reset();
        }
    });
});
